<template>
  <div class="user-profile-page min-h-screen bg-[#f6f8fa] text-[#1f2328]">
    <header class="profile-nav border-b border-[#d0d7de] bg-white">
      <div class="mx-auto flex min-h-16 max-w-[1280px] flex-wrap items-center gap-2 px-4 py-3 lg:px-8">
        <router-link class="profile-logo" to="/app" aria-label="返回控制面板"><i class="fa fa-cube"></i></router-link>
        <nav class="order-3 flex w-full items-center gap-1 overflow-x-auto sm:order-none sm:w-auto" aria-label="个人主页导航">
          <router-link class="profile-nav-link" to="/app"><i class="fa fa-arrow-left mr-1.5"></i>我的网盘</router-link>
          <router-link class="profile-nav-link" to="/explore">探索公开仓库</router-link>
          <router-link class="profile-nav-link" to="/teamwork">团队协作</router-link>
        </nav>
        <router-link class="profile-current-user" to="/app/profile" title="个人设置">{{ currentUserInitial }}</router-link>
      </div>
    </header>

    <main class="mx-auto max-w-[1280px] px-4 pb-14 pt-6 lg:px-8 lg:pt-8">
      <section v-if="loading" class="profile-skeleton" aria-label="正在加载用户主页"><aside><span></span><span></span><span></span></aside><div><span v-for="index in 6" :key="index"></span></div></section>
      <section v-else-if="error" class="profile-state"><i class="fa fa-exclamation-triangle"></i><h1>用户主页暂时无法加载</h1><p>{{ error }}</p><button type="button" @click="loadProfile">重新加载</button></section>
      <template v-else-if="profile">
        <div class="profile-breadcrumb" aria-label="面包屑"><router-link to="/explore">探索</router-link><i class="fa fa-angle-right"></i><span>{{ profile.displayName || profile.username }}</span></div>
        <div class="profile-layout">
          <aside class="profile-sidebar">
            <section class="profile-card profile-card--identity">
              <button class="profile-avatar" type="button" title="用户头像"><img v-if="profile.avatar" :src="profile.avatar" :alt="`${profile.displayName} 的头像`" /><span v-else>{{ profileInitial }}</span></button>
              <h1>{{ profile.displayName || profile.username }}</h1>
              <p class="profile-handle">@{{ profile.username }}</p>
              <p class="profile-bio">{{ profileBio }}</p>
              <dl class="profile-facts">
                <div><dt><i class="fa fa-folder-o"></i>公开仓库</dt><dd>{{ repositories.length }}</dd></div>
                <div><dt><i class="fa fa-code-fork"></i>Git 仓库</dt><dd>{{ gitRepositoryCount }}</dd></div>
                <div><dt><i class="fa fa-calendar-o"></i>加入平台</dt><dd>{{ profileCreatedAt }}</dd></div>
              </dl>
              <div class="profile-actions">
                <router-link v-if="isSelf" class="profile-action profile-action--primary" to="/app/profile"><i class="fa fa-pencil"></i>编辑个人资料</router-link>
                <router-link v-else class="profile-action profile-action--primary" :to="`/im/add-friend?keyword=${encodeURIComponent(profile.username)}`"><i class="fa fa-user-plus"></i>添加好友</router-link>
                <button class="profile-action" type="button" @click="shareProfile"><i class="fa fa-share-alt"></i>分享主页</button>
              </div>
              <p class="profile-data-note"><i class="fa fa-info-circle"></i>资料页仅展示该用户明确公开的仓库信息。</p>
            </section>
            <section class="profile-card profile-card--summary">
              <h2>公开资源概览</h2>
              <div class="summary-grid"><div><b>{{ totalFiles }}</b><span>文件</span></div><div><b>{{ formatSize(totalStorage) }}</b><span>已公开容量</span></div><div><b>{{ recentlyUpdated }}</b><span>30 天内更新</span></div></div>
              <p>Star、Fork、关注和粉丝等社交数据需要服务端独立提供统计接口，当前不以本地猜测替代。</p>
            </section>
          </aside>

          <section class="profile-content">
            <header class="profile-content__header">
              <div><p class="profile-kicker">PUBLIC PROFILE</p><h2>{{ profile.displayName || profile.username }} 的公开资源</h2><p>在这里浏览该用户发布的文件仓库和 Git 仓库。</p></div>
              <label class="profile-search"><i class="fa fa-search"></i><input v-model.trim="repoKeyword" placeholder="筛选仓库" /></label>
            </header>
            <nav class="profile-tabs" aria-label="用户主页内容" role="tablist">
              <button v-for="tab in tabs" :key="tab.key" type="button" :class="{ active: activeTab === tab.key }" role="tab" :aria-selected="activeTab === tab.key" @click="setTab(tab.key)"><i :class="tab.icon"></i>{{ tab.label }}<span>{{ tab.count }}</span></button>
            </nav>

            <section v-if="activeTab === 'overview'" class="profile-panel">
              <div class="pinned-section"><div class="panel-heading"><div><h3>置顶与近期活跃</h3><p>当前服务未暴露用户自定义置顶字段，以下按最近更新时间展示。</p></div><button type="button" class="small-link" @click="setTab('repositories')">查看全部<i class="fa fa-arrow-right"></i></button></div><div class="repo-list"><RepositoryRow v-for="repository in activeRepositories" :key="repository.spaceId" :repository="repository" @open="openRepository" /><div v-if="!activeRepositories.length" class="panel-empty"><i class="fa fa-clock-o"></i>暂无可展示的近期更新</div></div></div>
              <div class="activity-section"><div class="panel-heading"><div><h3>最近动态</h3><p>基于公开仓库创建和更新时间生成；不会将未授权的私有行为写入此处。</p></div></div><ol v-if="activityItems.length" class="activity-timeline"><li v-for="activity in activityItems" :key="`${activity.kind}-${activity.repository.spaceId}`"><span class="activity-icon"><i :class="activity.kind === 'created' ? 'fa fa-plus' : 'fa fa-refresh'"></i></span><div><p><b>{{ profile.displayName || profile.username }}</b>{{ activity.kind === 'created' ? ' 创建了公开仓库' : ' 更新了公开仓库' }} <button type="button" @click="openRepository(activity.repository)">{{ activity.repository.spaceName }}</button></p><time>{{ formatFullDate(activity.date) }}</time></div></li></ol><div v-else class="panel-empty"><i class="fa fa-rss"></i>暂无可公开的仓库动态</div></div>
            </section>

            <section v-else-if="activeTab === 'repositories'" class="profile-panel">
              <div class="panel-heading"><div><h3>公开仓库</h3><p>{{ filteredRepositories.length }} 个可访问仓库，按最近更新时间排列。</p></div><label class="profile-sort">排序<select v-model="repoSort"><option value="updated">最近更新</option><option value="created">最新创建</option><option value="files">文件数</option></select></label></div><div v-if="filteredRepositories.length" class="repo-list"><RepositoryRow v-for="repository in pagedRepositories" :key="repository.spaceId" :repository="repository" @open="openRepository" /></div><div v-else class="panel-empty"><i class="fa fa-folder-open-o"></i>没有匹配的公开仓库</div><nav v-if="repoPages > 1" class="profile-pagination"><button type="button" :disabled="repoPage === 1" @click="repoPage -= 1">上一页</button><span>第 {{ repoPage }} / {{ repoPages }} 页</span><button type="button" :disabled="repoPage === repoPages" @click="repoPage += 1">下一页</button></nav>
            </section>

            <section v-else class="profile-panel profile-panel--unavailable"><i class="fa fa-users"></i><h3>{{ activeTab === 'followers' ? '粉丝列表' : '关注列表' }}暂未开放</h3><p>公共用户目录接口当前仅返回用户资料和其公开仓库。待主业务服务提供经过权限过滤的关注关系后，此 Tab 会复用同一导航与分页结构接入。</p></section>
          </section>
        </div>
      </template>
    </main>
  </div>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/authStore'
import { getPublicUserProfileApi, type PublicSpaceDetail, type PublicUserProfile } from '@/api/modules/publicSpaces'

/** [REQ-PUBLIC-PROFILE-4.3~4.25] 仓库行复用公开用户资料中返回的仓库投影，避免向 IM 或空间私有表额外取数。 */
const RepositoryRow = defineComponent({
  name: 'PublicProfileRepositoryRow', props: { repository: { type: Object as () => PublicSpaceDetail, required: true } }, emits: ['open'],
  setup(props, { emit }) {
    const relative = (value?: string) => { if (!value) return '暂无更新时间'; const diff = Date.now() - new Date(value).getTime(); if (diff < 3600000) return `${Math.max(1, Math.floor(diff / 60000))} 分钟前`; if (diff < 86400000) return `${Math.floor(diff / 3600000)} 小时前`; return new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'short', day: 'numeric' }).format(new Date(value)) }
    return () => h('article', { class: 'public-repository-row', tabindex: 0, onClick: () => emit('open', props.repository), onKeyup: (event: KeyboardEvent) => event.key === 'Enter' && emit('open', props.repository) }, [
      h('span', { class: ['public-repository-row__icon', props.repository.resourceType === 'git' ? 'is-git' : ''] }, [h('i', { class: props.repository.resourceType === 'git' ? 'fa fa-code-fork' : 'fa fa-folder-o' })]),
      h('div', { class: 'public-repository-row__main' }, [h('h4', props.repository.spaceName), h('p', props.repository.description || '暂无仓库描述')]),
      h('div', { class: 'public-repository-row__meta' }, [h('span', [h('i', { class: 'fa fa-files-o' }), `${props.repository.fileCount || 0} 个文件`]), h('span', [h('i', { class: 'fa fa-clock-o' }), relative(props.repository.updatedAt || props.repository.createdAt)])]),
      h('i', { class: 'fa fa-angle-right public-repository-row__arrow' }),
    ])
  },
})

const route = useRoute(); const router = useRouter(); const authStore = useAuthStore()
const username = computed(() => String(route.params.username || ''))
const profile = ref<PublicUserProfile | null>(null)
const loading = ref(true); const error = ref(''); const activeTab = ref<'overview' | 'repositories' | 'followers' | 'following'>('overview')
const repoKeyword = ref(''); const repoSort = ref<'updated' | 'created' | 'files'>('updated'); const repoPage = ref(1); const pageSize = 8
const currentUserInitial = computed(() => String(authStore.user?.name || authStore.user?.account || 'U').slice(0, 1).toUpperCase())
const isSelf = computed(() => Boolean(profile.value && [authStore.user?.name, authStore.user?.account].filter(Boolean).includes(profile.value.username)))
const repositories = computed(() => profile.value?.repositories || [])
const profileInitial = computed(() => (profile.value?.displayName || profile.value?.username || '?').slice(0, 1).toUpperCase())
const profileBio = computed(() => `该用户已公开 ${repositories.value.length} 个可访问仓库。更详细的个人简介字段目前未由公共用户目录接口返回。`)
const profileCreatedAt = computed(() => { const earliest = repositories.value.map(item => item.createdAt).filter(Boolean).sort()[0]; return earliest ? formatMonth(earliest) : '未提供' })
const totalFiles = computed(() => repositories.value.reduce((total, item) => total + (item.fileCount || 0), 0))
const totalStorage = computed(() => repositories.value.reduce((total, item) => total + (item.usedBytes || 0), 0))
const gitRepositoryCount = computed(() => repositories.value.filter(item => item.resourceType === 'git').length)
const recentlyUpdated = computed(() => repositories.value.filter(item => item.updatedAt && Date.now() - dateValue(item.updatedAt) < 30 * 86400000).length)
const filteredRepositories = computed(() => [...repositories.value].filter(item => `${item.spaceName} ${item.description || ''}`.toLocaleLowerCase().includes(repoKeyword.value.toLocaleLowerCase())).sort((a, b) => repoSort.value === 'files' ? (b.fileCount || 0) - (a.fileCount || 0) : repoSort.value === 'created' ? dateValue(b.createdAt) - dateValue(a.createdAt) : dateValue(b.updatedAt) - dateValue(a.updatedAt)))
const activeRepositories = computed(() => [...repositories.value].sort((a, b) => dateValue(b.updatedAt) - dateValue(a.updatedAt)).slice(0, 4))
const repoPages = computed(() => Math.max(1, Math.ceil(filteredRepositories.value.length / pageSize)))
const pagedRepositories = computed(() => filteredRepositories.value.slice((repoPage.value - 1) * pageSize, repoPage.value * pageSize))
const activityItems = computed(() => repositories.value.flatMap(repository => [{ kind: 'created' as const, date: repository.createdAt, repository }, ...(repository.updatedAt && repository.updatedAt !== repository.createdAt ? [{ kind: 'updated' as const, date: repository.updatedAt, repository }] : [])]).filter(item => item.date).sort((a, b) => dateValue(b.date) - dateValue(a.date)).slice(0, 8))
const tabs = computed(() => [{ key: 'overview' as const, label: '概览', icon: 'fa fa-th-large', count: repositories.value.length }, { key: 'repositories' as const, label: '仓库', icon: 'fa fa-folder-o', count: repositories.value.length }, { key: 'followers' as const, label: '粉丝', icon: 'fa fa-users', count: '—' }, { key: 'following' as const, label: '关注', icon: 'fa fa-user-plus', count: '—' }])

function dateValue(value?: string) { const result = value ? new Date(value).getTime() : 0; return Number.isFinite(result) ? result : 0 }
function formatMonth(value?: string) { return value ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long' }).format(new Date(value)) : '未提供' }
function formatFullDate(value?: string) { return value ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '时间未提供' }
function formatSize(value: number) { if (!value) return '0 B'; const units = ['B', 'KB', 'MB', 'GB', 'TB']; const index = Math.min(Math.floor(Math.log(value) / Math.log(1024)), units.length - 1); return `${(value / 1024 ** index).toFixed(index ? 1 : 0)} ${units[index]}` }
function openRepository(repository: PublicSpaceDetail) { void router.push(`/repo/${encodeURIComponent(repository.spaceId)}`) }
function setTab(tab: typeof activeTab.value) { activeTab.value = tab; void router.replace({ query: { ...(tab !== 'overview' ? { tab } : {}) } }) }
async function shareProfile() { const url = window.location.href; try { await navigator.clipboard.writeText(url); window.alert('主页链接已复制') } catch { window.prompt('请复制主页链接', url) } }
async function loadProfile() { loading.value = true; error.value = ''; try { const response = await getPublicUserProfileApi(username.value); profile.value = response.data } catch (cause: unknown) { profile.value = null; error.value = cause instanceof Error ? cause.message : '用户资料请求失败，请稍后重试。' } finally { loading.value = false } }

watch(() => route.query.tab, value => { activeTab.value = ['repositories', 'followers', 'following'].includes(String(value)) ? value as typeof activeTab.value : 'overview' }, { immediate: true })
watch([repoKeyword, repoSort], () => { repoPage.value = 1 })
watch(repoPages, value => { repoPage.value = Math.min(repoPage.value, value) })
onMounted(async () => { await authStore.fetchUserInfo(); await loadProfile() })
</script>

<style>
.profile-nav { position:sticky;top:0;z-index:30;box-shadow:0 1px 0 rgba(31,35,40,.04); }.profile-logo { display:inline-flex;width:32px;height:32px;align-items:center;justify-content:center;border-radius:7px;background:#0969da;color:#fff; }.profile-nav-link { display:inline-flex;min-height:32px;align-items:center;border-radius:6px;padding:0 10px;color:#57606a;font-size:13px;white-space:nowrap; }.profile-nav-link:hover { background:#f6f8fa;color:#0969da; }.profile-current-user { display:inline-flex;width:32px;height:32px;align-items:center;justify-content:center;margin-left:auto;border:1px solid #d0d7de;border-radius:50%;background:#ddf4ff;color:#0969da;font-size:12px;font-weight:700; }.profile-breadcrumb { display:flex;align-items:center;gap:8px;margin-bottom:16px;color:#57606a;font-size:12px; }.profile-breadcrumb a { color:#0969da; }.profile-layout { display:grid;align-items:start;gap:22px;grid-template-columns:260px minmax(0,1fr); }.profile-sidebar { position:sticky;top:88px;display:flex;flex-direction:column;gap:14px; }.profile-card,.profile-panel { border:1px solid #d0d7de;border-radius:8px;background:#fff;box-shadow:0 1px 2px rgba(27,31,36,.04); }.profile-card { padding:18px; }.profile-card--identity { text-align:left; }.profile-avatar { display:inline-flex;width:94px;height:94px;align-items:center;justify-content:center;overflow:hidden;border:1px solid #d0d7de;border-radius:50%;background:#ddf4ff;color:#0969da;font-size:34px;font-weight:700; }.profile-avatar img { width:100%;height:100%;object-fit:cover; }.profile-card h1 { margin:13px 0 0;font-size:23px;letter-spacing:-.02em; }.profile-handle { margin:3px 0 0;color:#57606a;font-size:13px; }.profile-bio { margin:15px 0 0;color:#57606a;font-size:13px;line-height:1.65; }.profile-facts { margin:17px 0 0;border-top:1px solid #d8dee4; }.profile-facts div { display:flex;align-items:center;justify-content:space-between;padding:9px 0;border-bottom:1px solid #d8dee4;color:#57606a;font-size:12px; }.profile-facts dt i { width:17px;color:#57606a; }.profile-facts dd { margin:0;color:#24292f;font-weight:700; }.profile-actions { display:flex;flex-wrap:wrap;gap:7px;margin-top:16px; }.profile-action { display:inline-flex;min-height:32px;align-items:center;justify-content:center;gap:6px;border:1px solid #d0d7de;border-radius:6px;background:#f6f8fa;padding:0 10px;color:#24292f;font-size:12px;font-weight:600; }.profile-action:hover { border-color:#0969da;color:#0969da; }.profile-action--primary { border-color:#1f883d;background:#1f883d;color:#fff; }.profile-action--primary:hover { border-color:#1a7f37;background:#1a7f37;color:#fff; }.profile-data-note { margin:14px 0 0;color:#8c959f;font-size:11px;line-height:1.55; }.profile-data-note i { margin-right:4px; }.profile-card--summary h2 { margin:0;font-size:14px; }.summary-grid { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin-top:13px; }.summary-grid div { min-width:0;text-align:center; }.summary-grid b,.summary-grid span { display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap; }.summary-grid b { color:#24292f;font-size:14px; }.summary-grid span { margin-top:3px;color:#57606a;font-size:10px; }.profile-card--summary>p { margin:14px 0 0;color:#8c959f;font-size:11px;line-height:1.6; }.profile-content { min-width:0; }.profile-content__header { display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:16px; }.profile-kicker { margin:0;color:#0969da;font-size:11px;font-weight:800;letter-spacing:.14em; }.profile-content__header h2 { margin:5px 0 0;font-size:23px;letter-spacing:-.02em; }.profile-content__header p { margin:5px 0 0;color:#57606a;font-size:13px; }.profile-search { display:flex;min-width:220px;align-items:center;border:1px solid #d0d7de;border-radius:6px;background:#fff;padding:0 9px;color:#57606a; }.profile-search:focus-within { border-color:#0969da;box-shadow:0 0 0 3px rgba(9,105,218,.15); }.profile-search input { width:100%;height:34px;border:0;outline:0;background:transparent;padding-left:7px;color:#24292f;font-size:12px; }.profile-tabs { display:flex;overflow-x:auto;margin-bottom:16px;border-bottom:1px solid #d0d7de; }.profile-tabs button { display:inline-flex;align-items:center;gap:7px;border-bottom:2px solid transparent;padding:10px 12px;color:#57606a;font-size:13px;white-space:nowrap; }.profile-tabs button:hover,.profile-tabs button.active { border-bottom-color:#fd8c73;color:#24292f;font-weight:600; }.profile-tabs span { border-radius:999px;background:#eaeef2;padding:1px 5px;color:#57606a;font-size:10px; }.profile-panel { overflow:hidden; }.pinned-section,.activity-section { padding:20px; }.activity-section { border-top:1px solid #d8dee4;background:#f6f8fa; }.panel-heading { display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:13px; }.panel-heading h3 { margin:0;color:#24292f;font-size:15px; }.panel-heading p { margin:4px 0 0;color:#57606a;font-size:12px;line-height:1.55; }.small-link { display:inline-flex;align-items:center;gap:6px;padding-top:2px;color:#0969da;font-size:12px;white-space:nowrap; }.repo-list { overflow:hidden;border:1px solid #d0d7de;border-radius:7px;background:#fff; }.public-repository-row { display:grid;grid-template-columns:32px minmax(0,1fr) auto 16px;align-items:center;gap:10px;min-height:74px;border-bottom:1px solid #d8dee4;padding:10px 13px;cursor:pointer;transition:background .15s; }.public-repository-row:last-child { border-bottom:0; }.public-repository-row:hover,.public-repository-row:focus-visible { outline:0;background:#f6f8fa; }.public-repository-row__icon { display:inline-flex;width:30px;height:30px;align-items:center;justify-content:center;border-radius:6px;background:#ddf4ff;color:#0969da; }.public-repository-row__icon.is-git { background:#fff1e5;color:#bf8700; }.public-repository-row__main { min-width:0; }.public-repository-row__main h4 { overflow:hidden;margin:0;color:#0969da;font-size:13px;text-overflow:ellipsis;white-space:nowrap; }.public-repository-row__main p { overflow:hidden;margin:4px 0 0;color:#57606a;font-size:11px;text-overflow:ellipsis;white-space:nowrap; }.public-repository-row__meta { display:flex;align-items:center;gap:11px;color:#57606a;font-size:11px;white-space:nowrap; }.public-repository-row__meta i { margin-right:3px; }.public-repository-row__arrow { color:#57606a; }.activity-timeline { margin:0;padding:0;list-style:none; }.activity-timeline li { position:relative;display:flex;gap:11px;padding:0 0 17px; }.activity-timeline li:last-child { padding-bottom:0; }.activity-timeline li:not(:last-child)::before { position:absolute;top:27px;bottom:0;left:11px;width:1px;background:#d8dee4;content:''; }.activity-icon { position:relative;z-index:1;display:inline-flex;width:23px;height:23px;flex:0 0 23px;align-items:center;justify-content:center;border:1px solid #d0d7de;border-radius:50%;background:#fff;color:#0969da;font-size:10px; }.activity-timeline p { margin:1px 0 0;color:#57606a;font-size:12px;line-height:1.5; }.activity-timeline b { color:#24292f; }.activity-timeline button { color:#0969da;text-align:left; }.activity-timeline time { display:block;margin-top:3px;color:#8c959f;font-size:11px; }.panel-empty { display:flex;min-height:118px;align-items:center;justify-content:center;gap:8px;color:#8c959f;font-size:12px;text-align:center; }.profile-sort { display:flex;align-items:center;gap:6px;color:#57606a;font-size:12px;white-space:nowrap; }.profile-sort select { border:1px solid #d0d7de;border-radius:6px;background:#fff;padding:5px;color:#24292f;font-size:12px; }.profile-pagination { display:flex;align-items:center;justify-content:center;gap:10px;padding:16px;color:#57606a;font-size:12px; }.profile-pagination button { border:1px solid #d0d7de;border-radius:6px;background:#fff;padding:6px 10px;color:#24292f; }.profile-pagination button:disabled { opacity:.5;cursor:not-allowed; }.profile-panel--unavailable { display:flex;min-height:300px;flex-direction:column;align-items:center;justify-content:center;p